def human_size(nbytes):
    if nbytes == 0:
        return '0B'
    units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB']
    mag = 0
    while nbytes >= 1024 and mag < len(units):
        nbytes /= 1024.
        mag += 1
    return ('%.2f%s' % (nbytes, units[mag])).rstrip('0123456789')

